package run.ikaros.music;
import static org.mockito.Mockito.when; import java.util.List; import java.util.UUID; import org.junit.jupiter.api.Test; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import reactor.test.StepVerifier; import run.ikaros.storage.api.AttachmentAvailabilityStatus; import run.ikaros.storage.api.AttachmentKind; import run.ikaros.storage.api.AttachmentView; import run.ikaros.storage.api.StorageService;
class PersistentMusicDuplicateServiceTest { @Test void findsExistingTrackByContentIdentity(){UUID owner=UUID.randomUUID(),input=UUID.randomUUID(),existingAttachment=UUID.randomUUID(),trackId=UUID.randomUUID(); StorageService storage=org.mockito.Mockito.mock(StorageService.class); MusicAudioSourceRepository sources=org.mockito.Mockito.mock(MusicAudioSourceRepository.class); MusicTrackRepository tracks=org.mockito.Mockito.mock(MusicTrackRepository.class); AttachmentView request=new AttachmentView(input,UUID.randomUUID(),"new.mp3",AttachmentKind.ORIGINAL,"hash",42,"audio/mpeg",AttachmentAvailabilityStatus.READY); AttachmentView existing=new AttachmentView(existingAttachment,UUID.randomUUID(),"old.mp3",AttachmentKind.ORIGINAL,"hash",42,"audio/mpeg",AttachmentAvailabilityStatus.READY); when(storage.get(owner,input)).thenReturn(Mono.just(request)); when(storage.findByContentIdentity(owner,"hash",42)).thenReturn(Mono.just(List.of(request,existing))); when(sources.findAllByOwnerIdAndAttachmentId(owner,existingAttachment)).thenReturn(Flux.just(new MusicAudioSourceEntity(UUID.randomUUID(),owner,trackId,existingAttachment,"MP3","MPEG",42L,null,null,null,null,false,"AVAILABLE",0,null))); when(tracks.findById(trackId)).thenReturn(Mono.just(new MusicTrackEntity(trackId,owner,UUID.randomUUID(),"Existing Song",42L,null,false,0L))); StepVerifier.create(new PersistentMusicDuplicateService(storage,sources,tracks).find(owner,input)).expectNextMatches(v->v.size()==1&&v.get(0).trackId().equals(trackId)&&v.get(0).title().equals("Existing Song")).verifyComplete(); } }
